/* eslint-disable react-hooks/exhaustive-deps */
import React, { useEffect, useState } from 'react'
import { Typography, Spin, Empty, Row, Col, Alert, Icon, Button, message, Divider } from 'antd'
import EbEmptyPage from '../../../../../../components/EbEmptyPage/ebEmptypage'
import { useEmployeeDetail, useDeactivateParticipants, useDeactivateDependents } from '../../../state/Employee/hooks/useEmployee'
import { DEPENDENT_VIEW, employeeDetailErros, employeeDetailStates } from './constants'
import { divideArrayIntoSubArraysOfThree, renderDeactivateDependentsButton } from './utility'
import EmployeeDetailSection from './components/EmployeeDetailSection'
import DependentCard from './components/DependentCard'
import PermissionCheckerV2 from '../../../../../../components/permissionCheckerV2'
import { RowWithMargin } from '../../../CommonComponents'
import { useErrorContextValue, useLoaderContextValue, useResetError } from '@pasarpolis/common-react-hooks'
import { useResetState } from '../../../state/hooks'
import DeactivateParticipant from '../../EmployeeList/components/DeactivateParticipant'
import { DependentsSectionContainer } from './index.style'
import ECardSection from './components/ECardSection'
import PlanMappings from './components/PlanMappings'
import { ColTextAlignRight } from '../../../CommonComponents/index.style'

const { Title } = Typography

const EmployeeDetail = ({ history, match, ...props }) => {
  const [{ employeeDetailData }, request] = useEmployeeDetail()
  const [{
    EMPLOYEE_DETAIL_ERROR,
    DEACTIVATE_PARTICIPANTS_ERROR,
    DEACTIVATE_DEPENDENTS_ERROR,
    UPDATE_DEPENDENTS_ERROR,
    ADD_DEPENDENTS_ERROR,
    deactivateParticipantsStatus,
    employeeDetailStatus,
    deactivateDependentsStatus,
    updateDependentsStatus,
    addDependentsStatus
  }] = useErrorContextValue()
  const [{ EMPLOYEE_DETAIL_LOADER, DEACTIVATE_PARTICIPANTS_LOADER, DEACTIVATE_DEPENDENTS_LOADER, UPDATE_DEPENDENTS_LOADER, ADD_DEPENDENTS_LOADER }] = useLoaderContextValue()
  const { deactivateParticipantsData, deactivateParticipantsRequest } = useDeactivateParticipants()
  const [{ deactivateDependentsData }, deactivateDependentsRequest] = useDeactivateDependents()
  const { resetState } = useResetState()
  const [employeeData, setEmployeeData] = useState(null)
  const [dependentsData, setDependentsData] = useState([])
  const { resetError } = useResetError()

  const handleAddDependent = () => {
    setDependentsData(dependentsData => ([{ type: DEPENDENT_VIEW.ADD }, ...dependentsData]))
  }

  const handleCloseAddForm = () => {
    setDependentsData(dependentsData => dependentsData.slice(1))
  }

  const handleCloseEditForm = (dependentId) => {
    const originalDependentsData = dependentsData.map(dependent => {
      if (dependent.data && dependent.data.id === dependentId) {
        return { viewMode: DEPENDENT_VIEW.DISPLAY, data: dependent.data, type: DEPENDENT_VIEW.DISPLAY }
      }
      return dependent
    })
    setDependentsData(originalDependentsData)
  }

  const isEmployeeDisabled = employeeData && employeeData.status === 'DEACTIVATED'

  const goToEdit = () => {
    history.push({
      pathname: `${match.params.employeeId}/edit`,
      state: employeeDetailData && employeeDetailData.employee_data
    })
  }

  const getDetailData = () => {
    const query = {
      company_id: match.params.companyId,
      employee_id: match.params.employeeId
    }
    request({ query })
  }

  const handleDependentsEdit = (dependentId) => {
    const updatedDependentsData = dependentsData.map(dependent => {
      if (dependent.data && dependent.data.id === dependentId) {
        return { viewMode: DEPENDENT_VIEW.EDIT, data: dependent.data, type: DEPENDENT_VIEW.EDIT }
      }
      return dependent
    })
    setDependentsData(updatedDependentsData)
  }

  const handleDeactivateDependents = (dependentsData) => {
    return () => deactivateDependentsRequest({
      company_id: match.params.companyId, employeedependent_ids: dependentsData.filter(dependent => !!dependent.data).map(dependent => (dependent.data.id))
    })
  }

  useEffect(() => {
    if (deactivateParticipantsData && deactivateParticipantsData.data) {
      const { data } = deactivateParticipantsData
      if (Array.isArray(data.employee_failure) && data.employee_failure.length) {
        message.error('Could not deactivate employee. Please try again.')
      }
      if (Array.isArray(data.employee_success) && data.employee_success.length) {
        message.success('Employee deactivated successfully')
        history.push(`/employee-benefits/company-list/${match.params.companyId}/employee-list/`)
      }
      resetState(['deactivateParticipantsData', 'deactivateParticipantsStatus'])
      resetError(['DEACTIVATE_PARTICIPANTS_ERROR'])
    }
  }, [deactivateParticipantsData])

  useEffect(() => {
    if (!UPDATE_DEPENDENTS_ERROR && updateDependentsStatus === 'success') {
      message.success('Dependent updated successfully')
      getDetailData()
      resetState([
        'updateDependentsData'
      ])
      resetError([
        'EMPLOYEE_DETAIL_ERROR',
        'updateDependentsStatus'
      ])
    }
  }, [updateDependentsStatus])

  useEffect(() => {
    if (!ADD_DEPENDENTS_ERROR && addDependentsStatus === 'success') {
      message.success('Dependent added successfully')
      getDetailData()
      resetState([
        'addDependentsData'
      ])
      resetError([
        'ADD_DEPENDENTS_ERROR',
        'addDependentsStatus'
      ])
    }
  }, [addDependentsStatus])

  useEffect(() => {
    if (employeeDetailData && !EMPLOYEE_DETAIL_ERROR) {
      const { employee_data: employeeData, employee_dependent_data: dependentsData } = employeeDetailData
      setEmployeeData(employeeData)
      if (Array.isArray(dependentsData)) {
        const dependentsDataWithViewModeInfo = dependentsData.map(data => ({ viewMode: DEPENDENT_VIEW.DISPLAY, data: data }))
        setDependentsData(dependentsDataWithViewModeInfo)
      }
    }
  }, [employeeDetailData])

  useEffect(() => {
    if (deactivateDependentsData && deactivateDependentsData.data) {
      const { data } = deactivateDependentsData
      if (Array.isArray(data.employeedependent_failure) && data.employeedependent_failure.length) {
        message.error('Could not deactivate dependent. Please try again.')
      }
      if (Array.isArray(data.employeedependent_success) && data.employeedependent_success.length) {
        message.success('Dependent deactivated successfully')
        getDetailData()
      }
      resetState(['deactivateDependentsData', 'deactivateDependentsStatus'])
      resetError(['DEACTIVATE_DEPENDENTS_ERROR'])
    }
  }, [deactivateDependentsData])

  useEffect(() => {
    getDetailData()
    return () => {
      resetState(employeeDetailStates)
      resetError(employeeDetailErros)
    }
  }, [])
  return (

    <EbEmptyPage
      history={history}
      contentDisabled={isEmployeeDisabled}
      path={`/employee-benefits/company-list/${match.params.companyId}/employee-list/`}
    >
      {(DEACTIVATE_PARTICIPANTS_ERROR) && <Alert type='error' message={deactivateParticipantsStatus} banner />}
      {(EMPLOYEE_DETAIL_ERROR) && <Alert type='error' message={employeeDetailStatus} banner />}
      {(DEACTIVATE_DEPENDENTS_ERROR) && <Alert type='error' message={deactivateDependentsStatus} banner />}
      {(UPDATE_DEPENDENTS_ERROR) && <Alert type='error' message={updateDependentsStatus} banner />}
      {(ADD_DEPENDENTS_ERROR) && <Alert type='error' message={addDependentsStatus} banner />}
      <Spin
        spinning={!!(
          EMPLOYEE_DETAIL_LOADER ||
          DEACTIVATE_PARTICIPANTS_LOADER ||
          DEACTIVATE_DEPENDENTS_LOADER ||
          UPDATE_DEPENDENTS_LOADER ||
          ADD_DEPENDENTS_LOADER)}
      >
        <Row>
          <Col span={14}>
            <Title level={4}>
              Employee Detail
            </Title>
          </Col>
          <PermissionCheckerV2
            requiredPermission='ops.eb_edit_participant'
          >
            <ColTextAlignRight span={5}>
              <Button
                type='primary'
                title='Edit Employee'
                onClick={goToEdit}
                disabled={isEmployeeDisabled}
              >
                Edit Employee
                <Icon type='edit' />

              </Button>
            </ColTextAlignRight>
          </PermissionCheckerV2>
          <PermissionCheckerV2 requiredPermission='ops.eb_deactivate_participant'>
            <ColTextAlignRight span={5}>
              <DeactivateParticipant
                participantName={employeeData?.name}
                onSubmit={(values) => {
                  deactivateParticipantsRequest({
                    company_id: match.params.companyId,
                    employee_ids: [match.params.employeeId],
                    ...values
                  })
                }}
              >
                <Button
                  type='danger'
                  title='Deactivate Employee'
                  disabled={isEmployeeDisabled}
                >
                  Deactivate Employee
                  <Icon type='stop' />
                </Button>
              </DeactivateParticipant>
            </ColTextAlignRight>
          </PermissionCheckerV2>
        </Row>
        {employeeData
          ? (
            <>
              <EmployeeDetailSection
                employeeData={employeeData}
              />
              <Divider />
              <RowWithMargin />
              <Row>
                <Col>
                  <Title level={4}>
                    E-Card Data
                  </Title>
                </Col>
              </Row>
              <ECardSection employeeData={employeeData} />
              <Divider />
              {employeeData?.status !== 'UNPAID' && <PlanMappings participantsData={employeeDetailData} />}
              <RowWithMargin />
              <Row type='flex' justify='space-between'>
                <Col span={14}>
                  <Title level={4}>
                    Relationship Information
                  </Title>
                </Col>
                <PermissionCheckerV2
                  requiredPermission='ops.eb_add_participant'
                >
                  <ColTextAlignRight span={5}>
                    <Button
                      type='primary'
                      title='Add Dependent'
                      onClick={handleAddDependent}
                      disabled={
                        (dependentsData && dependentsData[0] && dependentsData[0].type === DEPENDENT_VIEW.ADD) ||
                        (isEmployeeDisabled)
                      }
                    >
                      Add Dependent
                      <Icon type='plus' />
                    </Button>
                  </ColTextAlignRight>
                </PermissionCheckerV2>

                <PermissionCheckerV2 requiredPermission='ops.eb_deactivate_participant'>
                  <ColTextAlignRight span={5}>
                    {renderDeactivateDependentsButton(handleDeactivateDependents, dependentsData, isEmployeeDisabled)}
                  </ColTextAlignRight>
                </PermissionCheckerV2>
              </Row>

              {(dependentsData)
                ? (
                  <DependentsSectionContainer>
                    {
                      divideArrayIntoSubArraysOfThree(dependentsData).map((dependents, index) => (
                        <RowWithMargin type='flex' className='align-stretch' gutter={18} key={index}>
                          {dependents.map(({ data: dependentData, viewMode, type }, i) => (
                            <Col className='height-parent' span={8} key={dependentData ? dependentData.id : `index-${i}`}>
                              <DependentCard
                                className='dependent-card'
                                match={match}
                                serial={(3 * index) + i + 1}
                                viewMode={viewMode}
                                handleCloseEditForm={handleCloseEditForm}
                                dependentData={dependentData}
                                handleDependentsEdit={handleDependentsEdit}
                                isEmployeeDisabled={isEmployeeDisabled}
                                handleCloseAddForm={handleCloseAddForm}
                                deactivateDependentsRequest={deactivateDependentsRequest}
                                type={type}
                              />
                            </Col>
                          ))}
                        </RowWithMargin>
                      ))
                  }
                  </DependentsSectionContainer>)
                : <Empty />}
            </>)
          : <Empty />}
      </Spin>
    </EbEmptyPage>
  )
}

export default EmployeeDetail
