import { useErrorContextValue, useLoaderContextValue, usePost, useResetError } from '@pasarpolis/common-react-hooks'
import { Alert, Button, Col, Divider, Form, Icon, message, Spin, Table, Typography } from 'antd'
import { useCallback, useEffect, useMemo, useState } from 'react'
import { useParams } from 'react-router'
import { RowWithMargin } from '../../../../../CommonComponents'
import { useEmployeeDetail } from '../../../../../state/Employee/hooks/useEmployee'
import { employeeApiConfig } from '../../../apiConfig'
import { PlanMappingsStyles } from './index.style'
import { planMappingColumns } from './utility'

const { Title } = Typography

const PlanMappings = ({ participantsData, form }) => {
  const { getFieldDecorator, resetFields, validateFields, getFieldsValue } = form
  const [, updateRequest] = usePost(employeeApiConfig.updatePlans)
  const [showForm, toggleForm] = useState(false)
  const params = useParams()
  const values = getFieldsValue()
  const [noPlanEmployeeIds, setNoPlanEmployeeIds] = useState([])
  const [{ UPDATE_PLANS_LOADER }] = useLoaderContextValue()
  const [{ UPDATE_PLANS_ERROR, updatePlansStatus, updatePlansErrorData }] = useErrorContextValue()
  const { resetError } = useResetError()
  const [, employeeDetailRequest] = useEmployeeDetail()

  const participants = useMemo(() => {
    const { employee_data: employeeData, employee_dependent_data: employeeDependentData } = participantsData
    return [employeeData, ...employeeDependentData].filter(({ status }) => ['PAID', 'PENDING'].includes(status))
  }, [participantsData])

  const columns = useMemo(() => {
    return planMappingColumns({ participants, getFieldDecorator, showForm, noPlanEmployeeIds })
  }, [participants, showForm, getFieldDecorator, noPlanEmployeeIds])

  const handleCancel = useCallback(() => {
    toggleForm(false)
    resetFields()
  }, [resetFields])

  const handleSubmit = useCallback((e) => {
    e.preventDefault()
    validateFields((err, values) => {
      if (!err) {
        const planMappings = Object.fromEntries(Object.entries(values.participant_plan_data))
        const toBeSentValues = {
          participant_plan_data: planMappings,
          company_id: params.companyId
        }
        updateRequest(toBeSentValues)
      }
    })
  }, [validateFields, params, updateRequest])

  useEffect(() => {
    if (values.participant_plan_data && showForm) {
      const planMappings = Object.fromEntries(Object.entries(values.participant_plan_data))
      for (const employeeId in planMappings) {
        let isAnyPlanPresent = false
        for (const benefitGroup in planMappings[employeeId]) {
          if (planMappings[employeeId][benefitGroup]) {
            isAnyPlanPresent = true
            break
          }
        }
        if (!isAnyPlanPresent) {
          if (!noPlanEmployeeIds.includes(employeeId)) {
            setNoPlanEmployeeIds(ids => [...ids, employeeId])
          }
        } else {
          if (noPlanEmployeeIds.includes(employeeId)) {
            setNoPlanEmployeeIds(ids => ids.filter(id => id !== employeeId))
          }
        }
      }
    }
  }, [values, noPlanEmployeeIds, showForm])

  useEffect(() => {
    if (updatePlansStatus === 'success') {
      message.success('Plans updated successfully')
      resetError(['updatePlansStatus'])
      const query = {
        company_id: params.companyId,
        employee_id: params.employeeId
      }
      employeeDetailRequest({ query })
      toggleForm(false)
    }
  }, [updatePlansStatus, resetError, employeeDetailRequest, params])

  useEffect(() => {
    return () => resetError(['updatePlansStatus', 'updatePlansErrorData', 'UPDATE_PLANS_ERROR'])
  }, [resetError])

  return (
    <PlanMappingsStyles>
      <Spin spinning={!!UPDATE_PLANS_LOADER}>
        {
          (UPDATE_PLANS_ERROR && !updatePlansErrorData?.error) &&
            <div className='mb-5'>
              <Alert type='error' message={updatePlansStatus} banner />
            </div>
        }
        <Form onSubmit={handleSubmit}>
          <RowWithMargin>
            <RowWithMargin type='flex' justify='space-between' align='middle'>
              <Col>
                <Title level={4}>
                  Plan Mappings
                </Title>
              </Col>
              <Col>
                {
                  showForm
                    ? (
                      <Button
                        onClick={handleCancel}
                        className='close-btn'
                        htmlType='button'
                      >
                        Close <Icon type='close' />
                      </Button>
                      )
                    : (
                      <Button
                        type='primary'
                        onClick={() => toggleForm(true)}
                        htmlType='button'
                      >
                        Edit Plan Mappings <Icon type='edit' />
                      </Button>
                      )
                }
              </Col>
            </RowWithMargin>
            <Table
              rowKey={({ id }) => id}
              dataSource={participants}
              columns={columns}
              pagination={false}
              scroll={{ x: ((columns?.length || 0) * 150 + 400) }}
            />
          </RowWithMargin>
          {
            showForm && (
              <RowWithMargin type='flex' justify='end'>
                <Col>
                  <Button
                    type='primary'
                    htmlType='submit'
                    className='submit-btn'
                    disabled={noPlanEmployeeIds?.length}
                  >
                    Update Mappings
                  </Button>
                </Col>
              </RowWithMargin>
            )
          }
        </Form>
        {
          showForm && (<Divider />)
        }
      </Spin>
    </PlanMappingsStyles>
  )
}
export default Form.create('plan-mappings')(PlanMappings)
