import { useResetError, useServiceRequest } from '@pasarpolis/common-react-hooks'
import { getFromSessionStorage } from '../../../../helpers/utility'
import { useEBContextValue } from '../context/index'
import { EB_ACTIONS } from './actions'
import useFileServiceRequest from './useFileUploadServiceRequest'
import loadash from 'lodash'
import { useCallback } from 'react'

export const useResetState = () => {
  const [, dispatch] = useEBContextValue()
  const resetState = useCallback((keys = []) => {
    dispatch(EB_ACTIONS.resetState(keys))
  }, [dispatch])
  return { resetState }
}

export const useFileUploadOnGcs = () => {
  const [{ gcsUploadData, gcsUploadStatus }, dispatch] = useEBContextValue()
  const { resetState } = useResetState()
  const { resetError } = useResetError()
  //  follow this
  const [callApi] = useFileServiceRequest(dispatch)
  const uploadRequest = async (payload = {}) => {
    resetState(['gcsUploadData'])
    resetError(['GCS_UPLOAD_ERROR', 'gcsUploadStatus'])
    await callApi(EB_ACTIONS.gcsUpload(payload))
  }
  return [{ gcsUploadData, gcsUploadStatus }, uploadRequest]
}

