export const useLeadConfig = () => {
  const leadDashboardConfigDataKey = 'lead-dashboard-config-data'
  const leadConfigFromSessionStorage = getFromSessionStorage(leadDashboardConfigDataKey)
  const [{ leadConfigData }, dispatch] = useEBContextValue()
  if (!leadConfigFromSessionStorage && leadConfigData && (!loadash.isEmpty(leadConfigData))) {
    window.sessionStorage.setItem(leadDashboardConfigDataKey, JSON.stringify(leadConfigData))
  }

  const [callApi] = useServiceRequest(dispatch)

  const leadConfigRequest = useCallback((payload = {}) => {
    const leadConfigFromSessionStorage = getFromSessionStorage(leadDashboardConfigDataKey)
    if (leadConfigFromSessionStorage) {
      dispatch(EB_ACTIONS.updateLeadConfig(leadConfigFromSessionStorage))
    } else {
      callApi(EB_ACTIONS.getLeadConfig())
    }
  }, [dispatch, callApi])
  return { leadConfigData, leadConfigRequest }
}

