import React from 'react'
import { Card, Row, Col, Button, Icon } from 'antd'
import { DEPENDENT_VIEW } from '../../constants'
import DependentDetail from '../DependentDetail/DependentDetail'
import AddEditDependentForm from '../AddEditDependentForm/addEditDependentForm'
import EditAndCloseButton from './editAndCloseButton'
import PermissionCheckerV2 from '../../../../../../../../components/permissionCheckerV2'
import DeactivateParticipant from '../../../../EmployeeList/components/DeactivateParticipant'

const dependentCountText = (index) => `Relationship ${index}`
const isDependentDisabled = (status) => status === 'DEACTIVATED'

const DependentCard = ({
  type,
  serial,
  viewMode,
  handleCloseEditForm,
  dependentData,
  handleDependentsEdit,
  isEmployeeDisabled,
  handleCloseAddForm,
  deactivateDependentsRequest,
  className,
  match
}) => {
  return (
    <Card
      title={type === DEPENDENT_VIEW.ADD ? 'Add New Dependent' : dependentCountText(serial)}
      key={serial}
      bordered
      className={className}
      extra={(
        <Row gutter={8}>
          <PermissionCheckerV2
            requiredPermission='ops.eb_edit_participant'
          >
            <Col span={12}>
              <EditAndCloseButton
                viewMode={viewMode}
                dependentData={dependentData}
                handleCloseAddForm={handleCloseAddForm}
                handleCloseEditForm={handleCloseEditForm}
                handleDependentsEdit={handleDependentsEdit}
                isEmployeeDisabled={isEmployeeDisabled}
                isDependentDisabled={isDependentDisabled}
              />
            </Col>
          </PermissionCheckerV2>
          {type === DEPENDENT_VIEW.ADD
            ? null
            : (
              <PermissionCheckerV2
                requiredPermission='ops.eb_deactivate_participant'
              >
                <Col span={12}>
                  <DeactivateParticipant
                    onSubmit={(values) => deactivateDependentsRequest({
                      company_id: match.params.companyId,
                      employeedependent_ids: [dependentData.id],
                      ...values
                    })}
                    participantName={dependentData?.name}
                    statusKey='deactivateDependentsStatus'
                  >
                    <Button
                      title='Deactivate Dependent'
                      type='danger'
                      disabled={isEmployeeDisabled || isDependentDisabled(dependentData.status)}
                    >
                      <Icon type='stop' />
                    </Button>
                  </DeactivateParticipant>
                </Col>
              </PermissionCheckerV2>
              )}
        </Row>)}
    >
      {viewMode === DEPENDENT_VIEW.DISPLAY
        ? (
          <DependentDetail
            dependentData={dependentData}
          />
          )
        : (
          <AddEditDependentForm
            type={type}
            data={dependentData}
            employeeId={match.params.employeeId}
            companyId={match.params.companyId}
          />
          )}
    </Card>
  )
}
export default DependentCard
