import { Form, Select, Typography } from 'antd'

const { Text } = Typography

export const planMappingColumns = ({ participants, showForm, getFieldDecorator, noPlanEmployeeIds }) => {
  const alreadyAddedBenefitGroups = {}
  const columns = [
    {
      key: 1,
      title: 'Participant Name',
      dataIndex: 'name',
      width: 150,
      render: (name, employeeData) => (
        <div>
          <div>{name}</div>
          {
            showForm && noPlanEmployeeIds.includes(String(employeeData.id)) && (
              <div>
                <Text type='danger'>Atleast 1 plan is required for this participant</Text>
              </div>
            )
          }
        </div>
      )
    },
    {
      key: 2,
      title: 'Relation',
      render: rowData => rowData?.relation_with_employee || 'Employee',
      width: 150
    }
  ]
  for (const participant of participants) {
    const { plan_data: planData } = participant
    if (Array.isArray(planData) && planData.length) {
      for (const plan of planData) {
        const { benefit_group: planBenefitGroup } = plan || {}
        if (planBenefitGroup && !alreadyAddedBenefitGroups[planBenefitGroup.slug]) {
          columns.push({
            key: planBenefitGroup.slug,
            title: planBenefitGroup.name,
            width: 150,
            render: rowData => {
              const participantPlanForThisBenefitGroup = rowData?.plan_data?.find(plan => plan.benefit_group.slug === planBenefitGroup?.slug)
              if (!participantPlanForThisBenefitGroup) return null
              if (showForm) {
                return (
                  <Form.Item>
                    {
                      getFieldDecorator(`participant_plan_data.${rowData.id}.${planBenefitGroup.slug}`, {
                        initialValue: participantPlanForThisBenefitGroup?.participant_plan?.id
                      })(
                        <Select
                          allowClear
                          disabled={rowData?.status !== 'PAID'}
                        >
                          {
                            participantPlanForThisBenefitGroup?.plans?.map(planData => (
                              <Select.Option
                                key={planData.id}
                                value={planData.id}
                              >
                                {planData.name}
                              </Select.Option>
                            ))
                          }
                        </Select>
                      )
                    }
                  </Form.Item>
                )
              } else {
                const plans = participantPlanForThisBenefitGroup?.plans
                const planId = participantPlanForThisBenefitGroup?.participant_plan?.id
                const planName = plans?.find(({ id }) => planId === id)?.name
                return planName
              }
            }
          })
          alreadyAddedBenefitGroups[planBenefitGroup.slug] = true
        }
      }
    }
  }
  return columns
}
