import moment from 'moment'
import { formattedPhoneNumber } from '../../../../../../../../helpers/utility'

export const getEditFieldValues = (data) => ({
  name: {
    value: data.name || ''
  },
  dob: {
    value: data.dob ? moment(data.dob, 'YYYY-MM-DD') : null
  },
  gender: {
    value: data.gender
  },
  relation_with_employee: {
    value: data.relation_with_employee
  },
  phone: {
    value: data.phone ? formattedPhoneNumber(data.phone) : ''
  },
  plan: {
    value: data.plan || ''
  },
  email: {
    value: data.email || ''
  },
  effective_join_date: {
    value: data.effective_join_date ? moment(data.effective_join_date, 'YYYY-MM-DD') : null
  },
  'policy_data.card_number': {
    value: data?.policy_data?.card_number
  },
  'policy_data.company_name': {
    value: data?.policy_data?.company_name
  },
  'policy_data.policy_number': {
    value: data?.policy_data?.policy_number
  }
})
