import React from 'react'
import { Row, Button, Icon } from 'antd'
import LayoutContentWrapper from '../utility/layoutWrapper'
import { EbEmptyPageContent } from './index.style'

const EbEmptyPage = ({ history, path = undefined, contentDisabled = false, ...props }) => {
  const goBack = () => {
    if (path) {
      history.push(path)
    } else {
      history.goBack()
    }
  }

  return (
    <LayoutContentWrapper>
      <Row>
        <Button onClick={goBack}>
          <Icon type='arrow-left' />
          Back
        </Button>
      </Row>
      <EbEmptyPageContent contentDisabled={contentDisabled}>
        {props.children}
      </EbEmptyPageContent>
    </LayoutContentWrapper>
  )
}

export default EbEmptyPage
