/* eslint-disable react-hooks/exhaustive-deps */
import React, { useEffect } from 'react'
import {
  Spin,
  Row,
  Col,
  Button,
  Form,
  Input,
  Select,
  DatePicker,
  Divider
} from 'antd'
import { ColTextAlignCenter } from '../../../../../CommonComponents/index.style'
import { dependentFormItemConfigs } from './constants'
import { useUpdateDependents, useAddDependents } from '../../../../../state/Employee/hooks/useEmployee'
import { DEPENDENT_VIEW } from '../../constants'
import { getEditFieldValues } from './utility'
import { StyledFormItem } from './index.style'
import { RowWithMargin } from '../../../../../CommonComponents'
import { useErrorContextValue } from '@pasarpolis/common-react-hooks'
import { addEditDependentValidations } from './validations'

const { Option } = Select

const formLayout = {
  labelCol: { span: 8 },
  wrapperCol: { span: 16 }
}

const AddEditDependentForm = ({ form, type, data, companyId, employeeId, ...props }) => {
  const [, updateDependentsRequest] = useUpdateDependents()
  const [, addDependentsRequest] = useAddDependents()
  const [{ UPDATE_DEPENDENTS_ERROR, ADD_DEPENDENTS_ERROR, updateDependentsErrorData, addDependentsErrorData }] = useErrorContextValue()
  const { getFieldDecorator } = form
  const isEDJRequired = !!(data?.status === 'UNPAID' || data?.effective_join_date)

  const handleSubmit = (e) => {
    e.preventDefault()
    form.validateFields((err, values) => {
      const valuesToBeSent = {
        ...values,
        dob: values.dob ? values.dob.format('YYYY-MM-DD') : '',
        effective_join_date: values.effective_join_date?.format('YYYY-MM-DD')
      }
      if (!(Object.values(values.policy_data).reduce((prevValue, value) => prevValue || !!value))) {
        delete valuesToBeSent.policy_data
      }
      if (!err) {
        switch (type) {
          case DEPENDENT_VIEW.EDIT:
            updateDependentsRequest({
              employee_dependent_data: { ...valuesToBeSent, relationship: valuesToBeSent.relation_with_employee },
              company_id: companyId,
              employee_id: employeeId,
              employee_dependent_id: data.id
            })
            break
          case DEPENDENT_VIEW.ADD:
            addDependentsRequest({
              employee_dependents: [valuesToBeSent],
              company_id: companyId,
              employee_id: employeeId
            })
            break
          default:
            break
        }
      }
    })
  }

  useEffect(() => {
    if (UPDATE_DEPENDENTS_ERROR) {
      if (updateDependentsErrorData && updateDependentsErrorData.error) {
        const { error } = updateDependentsErrorData
        for (const key in error) {
          const values = form.getFieldsValue()
          if (['policy_number', 'company_name', 'card_number'].includes(key)) {
            form.setFields({
              [`policy_data.${key}`]: {
                value: values.policy_data?.[key],
                errors: Array.isArray(error?.[key]) ? error?.[key].map(err => new Error(err)) : null
              }
            })
            continue
          }
          form.setFields({
            [key]: {
              value: values[key],
              errors: Array.isArray(error[key]) && error[key].map(err => new Error(err))
            }
          })
        }
      }
    }
  }, [UPDATE_DEPENDENTS_ERROR])

  useEffect(() => {
    if (ADD_DEPENDENTS_ERROR) {
      if (addDependentsErrorData && addDependentsErrorData.error) {
        const errorArray = addDependentsErrorData.error.employee_dependents
        if (Array.isArray(errorArray)) {
          const error = errorArray[0]
          const values = form.getFieldsValue()
          for (const key in error) {
            form.setFields({
              [key]: {
                value: values[key],
                errors: Array.isArray(error[key]) && error[key].map(err => new Error(err))
              }
            })
          }
        }
      }
    }
  }, [ADD_DEPENDENTS_ERROR])

  useEffect(() => {
    if (type === DEPENDENT_VIEW.EDIT && data) {
      form.setFields(getEditFieldValues(data))
    }
  }, [type, data])

  return (
    <Spin
      spinning={false}
    >
      <Form
        onSubmit={handleSubmit}
        // layout='horizontal'
      >
        <Row>
          <Col span={24}>
            <StyledFormItem
              hasFeedback
              label='Name'
              {...formLayout}
            >
              {
                getFieldDecorator('name', dependentFormItemConfigs.name)(<Input />)
              }
            </StyledFormItem>
          </Col>
          <Col span={24}>

            <StyledFormItem
              required
              hasFeedback
              label='Date of Birth'
              {...formLayout}
            >
              {
                getFieldDecorator('dob', dependentFormItemConfigs.dob)(
                  <DatePicker
                    format='YYYY-MM-DD'
                    disabledDate={date => date.isAfter(new Date(), 'day')}
                  />
                )
              }
            </StyledFormItem>
          </Col>
          <Col span={24}>
            <StyledFormItem
              hasFeedback
              label='Relationship'
              {...formLayout}
            >
              {
                getFieldDecorator(
                  'relation_with_employee',
                  dependentFormItemConfigs.relationship
                )(
                  <Select>
                    <Option value='Pasangan'>Pasangan</Option>
                    <Option value='Anak'>Anak</Option>
                  </Select>
                )
              }

            </StyledFormItem>
          </Col>
          <Col span={24}>
            <StyledFormItem
              required
              hasFeedback
              label='Gender'
              {...formLayout}
            >
              {
                getFieldDecorator(
                  'gender',
                  dependentFormItemConfigs.gender
                )(
                  <Select>
                    <Option value='Perempuan'>Perempuan</Option>
                    <Option value='Laki-laki'>Laki-laki</Option>
                  </Select>
                )
              }
            </StyledFormItem>
          </Col>
          <Col span={24}>
            <StyledFormItem
              hasFeedback
              label='Plan'
              {...formLayout}
            >
              {
                getFieldDecorator('plan', dependentFormItemConfigs.plan)(<Input />)
              }
            </StyledFormItem>
          </Col>
          <Col span={24}>
            <StyledFormItem
              required={isEDJRequired}
              hasFeedback
              label='EDJ'
              extra='Effective Date of Join'
              {...{ wrapperCol: { span: 16 }, labelCol: { span: 8 } }}
            >
              {
                getFieldDecorator('effective_join_date', dependentFormItemConfigs.effectiveJoinDate(isEDJRequired))(
                  <DatePicker
                    format='YYYY-MM-DD'
                  />
                )
              }
            </StyledFormItem>
          </Col>
          <Col span={24}>
            <RowWithMargin />
          </Col>
          <Divider />
          <h3>E-Card Data</h3>
          <Col span={24}>
            <StyledFormItem
              hasFeedback
              label='Company'
              {...{ wrapperCol: { span: 16 }, labelCol: { span: 8 } }}
            >
              {
                getFieldDecorator('policy_data.company_name', {
                  validateTrigger: 'onBlur',
                  rules: addEditDependentValidations.companyName(form)
                })(
                  <Input maxLength='27' />
                )
              }
            </StyledFormItem>
          </Col>
          <Col span={24}>
            <StyledFormItem
              hasFeedback
              label='Policy No'
              {...{ wrapperCol: { span: 16 }, labelCol: { span: 8 } }}
            >
              {
                getFieldDecorator('policy_data.policy_number', {
                  validateTrigger: 'onBlur',
                  rules: addEditDependentValidations.policyNumber(form)
                })(
                  <Input maxLength='27' />
                )
              }
            </StyledFormItem>
          </Col>
          <Col span={24}>
            <StyledFormItem
              hasFeedback
              label='Card Number'
              {...{ wrapperCol: { span: 16 }, labelCol: { span: 8 } }}
            >
              {
                getFieldDecorator('policy_data.card_number', {
                  validateTrigger: 'onBlur',
                  rules: addEditDependentValidations.cardNumber(form)
                })(
                  <Input maxLength='27' />
                )
              }
            </StyledFormItem>
          </Col>
        </Row>
        <RowWithMargin>
          <ColTextAlignCenter span={24}>
            <Button type='primary' htmlType='submit'>Submit</Button>
          </ColTextAlignCenter>
        </RowWithMargin>
      </Form>
    </Spin>

  )
}

export default Form.create()(AddEditDependentForm)
