import ebUrls from '../../../../../request/urls/employeeBenefit'

const actions = {
  EMPLOYEE_DETAIL_REQUEST: 'EMPLOYEE_DETAIL_REQUEST',
  EMPLOYEE_DETAIL: 'EMPLOYEE_DETAIL',
  DEACTIVATE_PARTICIPANTS_REQUEST: 'DEACTIVATE_PARTICIPANTS_REQUEST',
  DEACTIVATE_PARTICIPANTS: 'DEACTIVATE_PARTICIPANTS',
  DEACTIVATE_DEPENDENTS_REQUEST: 'DEACTIVATE_DEPENDENTS_REQUEST',
  DEACTIVATE_DEPENDENTS: 'DEACTIVATE_DEPENDENTS',
  ADD_DEPENDENTS_REQUEST: 'ADD_DEPENDENTS_REQUEST',
  ADD_DEPENDENTS: 'ADD_DEPENDENTS',
  UPDATE_DEPENDENTS_REQUEST: 'UPDATE_DEPENDENTS_REQUEST',
  UPDATE_DEPENDENTS: 'UPDATE_DEPENDENTS',

  geEmployeeDetails: payload => ({
    type: actions.EMPLOYEE_DETAIL_REQUEST,
    payload: {
      ...payload,
      method: 'get',
      url: ebUrls.employeeDetails
    }
  }),
  deactivateParticipant: payload => ({
    type: actions.DEACTIVATE_PARTICIPANTS_REQUEST,
    payload: {
      ...payload,
      method: 'post',
      url: ebUrls.deactivateParticipants
    }
  }),
  deactivateDependent: payload => ({
    type: actions.DEACTIVATE_DEPENDENTS_REQUEST,
    payload: {
      ...payload,
      method: 'post',
      url: ebUrls.deactivateDependents
    }
  }),
  addDependents: payload => ({
    type: actions.ADD_DEPENDENTS_REQUEST,
    payload: {
      ...payload,
      method: 'post',
      url: ebUrls.addDependents
    }
  }),
  updateDependents: payload => ({
    type: actions.UPDATE_DEPENDENTS_REQUEST,
    payload: {
      ...payload,
      method: 'post',
      url: ebUrls.updateDependents
    }
  })
}

export default actions
