import { ApiContextProvider } from '@pasarpolis/common-react-hooks'
import React from 'react'
import { EBContextProvider } from '../../context'
import reducer from '../../state/Employee/reducers'
import EmployeeList from './containers'

function Users (props) {
  return (
    <EBContextProvider reducer={reducer} pageName='Employee'>
      <ApiContextProvider>
        <EmployeeList {...props} />
      </ApiContextProvider>
    </EBContextProvider>
  )
}

export default Users
