import React from 'react'
import { Popconfirm, Button, Icon } from 'antd'

export const divideArrayIntoSubArraysOfThree = (arr = []) => {
  const arrParam = [...arr]
  const newArray = []
  while (arrParam.length) {
    newArray.push(arrParam.splice(0, 3))
  }
  return newArray
}

export function renderDeactivateDependentButton (deactivateDependentsRequest, match, dependentData, isEmployeeDisabled, isDependentDisabled) {
  return (
    <Popconfirm
      placement='top'
      title='Are you sure you want to do this ?'
      onConfirm={() => deactivateDependentsRequest({ company_id: match.params.companyId, employeedependent_ids: [dependentData.id] })}
      okText='Yes'
      cancelText='No'
      disabled={isEmployeeDisabled || isDependentDisabled(dependentData.status)}
    >
      <Button
        type='danger'
        title='Deactivate Dependent'
        ghost
        disabled={isEmployeeDisabled || isDependentDisabled(dependentData.status)}
      >
        <Icon type='stop' />
      </Button>
    </Popconfirm>
  )
}

export function renderDeactivateDependentsButton (handleDeactivateDependents, dependentsData, isEmployeeDisabled) {
  return (
    <Popconfirm
      placement='top'
      title='Are you sure you want to do this ?'
      onConfirm={handleDeactivateDependents(dependentsData)}
      okText='Yes'
      cancelText='No'
      disabled={
        isEmployeeDisabled ||
        !dependentsData.filter(dependent => dependent.data && dependent.data.status !== 'DEACTIVATED').length
      }
    >
      <Button
        type='danger'
        title='Deactivate Dependents'
        disabled={
          isEmployeeDisabled ||
          !dependentsData.filter(dependent => dependent.data && dependent.data.status !== 'DEACTIVATED').length
        }
      >
        Deactivate Dependents
        <Icon type='stop' />
      </Button>
    </Popconfirm>
  )
}
