import React from 'react'
import { Button, Icon } from 'antd'
import { DEPENDENT_VIEW } from '../../constants'

const EditAndCloseButton = ({
  viewMode,
  dependentData,
  handleCloseEditForm,
  handleDependentsEdit,
  handleCloseAddForm,
  isEmployeeDisabled,
  isDependentDisabled
}) => {
  switch (viewMode) {
    case DEPENDENT_VIEW.EDIT:
      return (
        <Button
          type='primary'
          title='Close'
          onClick={() => handleCloseEditForm(dependentData.id)}
          ghost
        >
          <Icon type='close' />
        </Button>
      )
    case DEPENDENT_VIEW.DISPLAY:
      return (
        <Button
          type='primary'
          title='Edit Dependent'
          ghost
          onClick={() => handleDependentsEdit(dependentData.id)}
          disabled={isEmployeeDisabled || isDependentDisabled(dependentData.status)}
        >
          <Icon type='edit' />
        </Button>
      )
    default:
      return (
        <Button
          type='primary'
          title='Close'
          ghost
          onClick={handleCloseAddForm}
        >
          <Icon type='close' />
        </Button>
      )
  }
}
export default EditAndCloseButton
